// ~할 수 있는 (Able)
interface Flyable {
    void fly(); // public abstract 생략됨
}

interface Swimable {
    void swim();
}

// 다중 구현 가능 (콤마 ,)
class Duck implements Flyable, Swimable {
    public void fly() {
        System.out.println("Duck flying");
    }
    public void swim() {
        System.out.println("Duck swimming");
    }
}

public class Main {
    public static void main(String[] args) {
        Duck d = new Duck();
        d.fly();
        d.swim();

        Flyable f = new Duck();
        f.fly();
        // f.swim(); // 에러! Flyable로는 날 수만 있음
    }
}
